/* ---------- Activity heatmap ---------- */
.hmx{padding:var(--dm-s-4);display:flex;flex-direction:column;gap:10px}
/* the ramp (owner, 20 Nov: "saturate the greens and blues"): from a light tint of the chart's mark colour to that colour at
   full strength, mixed in oklch so the steps between stay vivid rather than greying. The busiest cells, and the key's More,
   are the mark colour a touch toward the text, so they keep 3:1 on the card with room to spare (the blue in Soft and Clean,
   Blueprint's green in light and its lime in dark), and the key shows the same ramp as the cells. In dark mode the quiet end
   is a deeper tint, so it still reads against the card */
.hmx{--dm-hm-hi:color-mix(in oklch,var(--dm-accent-mark,var(--dm-accent)) 92%,var(--dm-fg));--dm-hm-lo:color-mix(in oklch,var(--dm-hm-hi) 13%,var(--dm-surface))}
@media (prefers-color-scheme:dark){:root:not([data-theme="light"]) .hmx{--dm-hm-lo:color-mix(in oklch,var(--dm-hm-hi) 22%,var(--dm-surface))}}
:root[data-theme="dark"] .hmx{--dm-hm-lo:color-mix(in oklch,var(--dm-hm-hi) 22%,var(--dm-surface))}
/* the head sits over a hairline in every style (owner, 21 Nov), 10px from it on each side as the card's other gaps */
.hmx-h{display:flex;align-items:center;justify-content:space-between;gap:10px;padding-bottom:10px;border-bottom:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent)}
.hmx-h>div:first-child{display:flex;flex-direction:column;font-size:13.5px;line-height:1.4}
.hmx-h b{font-weight:500}
.hmx-st{font-size:12px}
.hmx-sg button{font-size:12px;height:26px;padding:0 9px}
/* the day names, the cells and the hour names sit in one grid, so the hour names line up with the cells; on a phone the
   grid scrolls sideways (below) and the day names stay put */
.hmx-sc{display:grid;grid-template-columns:auto minmax(0,1fr);gap:6px}
.hmx-days{display:grid;grid-template-rows:repeat(7,1fr);gap:3px;font-size:10px}
.hmx-days span{display:flex;align-items:center;height:100%}
.hmx-grid{display:grid;grid-template-columns:repeat(24,minmax(0,1fr));gap:3px;min-width:0}
.hmx-grid i{aspect-ratio:1;border-radius:var(--dm-r-tiny,3px);background:color-mix(in oklch,var(--dm-hm-hi) min(var(--dm-a) * 118%,100%),var(--dm-hm-lo));transition:background .5s var(--dm-ease),transform .2s;max-width:100%}
@media (hover:hover) and (pointer:fine){.hmx-grid i:hover{transform:scale(1.35);box-shadow:0 0 0 1.5px var(--dm-surface);position:relative;z-index:1}}
.hmx-f{grid-column:2;display:grid;grid-template-columns:repeat(4,1fr);font-size:10.5px}
.hmx-f .x{display:none}
/* phones, and narrow cards: the grid scrolls sideways by touch or trackpad in 20px cells (about half the day on a phone, a
   little more on a wider card, never bigger cells for a wider card), starting at the latest hours. The edge the grid runs on
   past fades out, and the hour names come every three hours */
.hmx{container-type:inline-size}
@container (max-width:400px){
  .hmx-sc{grid-template-columns:34px calc(24 * 20px + 23 * 4px);column-gap:0;overflow-x:auto;overscroll-behavior-x:contain;scrollbar-width:none;scroll-snap-type:x proximity;scroll-padding-left:34px;
    --dm-fl:0px;--dm-fr:0px;-webkit-mask-image:linear-gradient(to right,#000 34px,transparent 34px,#000 calc(34px + var(--dm-fl)),#000 calc(100% - var(--dm-fr)),transparent);mask-image:linear-gradient(to right,#000 34px,transparent 34px,#000 calc(34px + var(--dm-fl)),#000 calc(100% - var(--dm-fr)),transparent)}
  .hmx-sc::-webkit-scrollbar{display:none}
  .hmx-sc.ml{--dm-fl:16px}.hmx-sc.mr{--dm-fr:16px}
  .hmx-days{position:sticky;left:0;z-index:2;background:var(--dm-surface);gap:4px;padding-right:6px;font-size:10.5px}
  /* and the corner under the day names covers the hour names as they scroll past */
  .hmx-sc::after{content:"";grid-row:2;grid-column:1;position:sticky;left:0;z-index:2;background:var(--dm-surface)}
  .hmx-grid{gap:4px}
  .hmx-grid i{border-radius:calc(4px * var(--dm-rk-s,var(--dm-rk)));scroll-snap-align:start}
  .hmx-f{grid-template-columns:repeat(8,1fr)}
  .hmx-f .x{display:block}
}
.hmx-lg{align-self:flex-end;display:flex;align-items:center;gap:3px;font-size:10.5px;line-height:1.2}
/* the key's squares are the cells a size down: the same shades, and corners as round for their size */
.hmx-lg i{width:9px;height:9px;border-radius:calc(var(--dm-r-tiny,2.67px) * .75);background:color-mix(in oklch,var(--dm-hm-hi) min(var(--dm-a) * 118%,100%),var(--dm-hm-lo))}
/* Clean (owner, 17 and 18 Nov): the content 16px in from every edge, and a cell under the pointer is ringed in a quiet grey
   rather than growing */
:root[data-style="clean"] .hmx.panel,:root [data-style="clean"] .hmx.panel,:root [data-style="clean"].hmx.panel{padding:16px}
:root[data-style="clean"] .hmx-h,:root [data-style="clean"] .hmx-h,:root [data-style="clean"].hmx-h{border-bottom-color:var(--dm-line)}
/* Clean: the Less to More key sits in the card's off-white foot strip, its words 16px in (owner, 21 Nov) */
:root[data-style="clean"] .hmx.panel .hmx-lg,:root [data-style="clean"] .hmx.panel .hmx-lg,:root [data-style="clean"].hmx.panel .hmx-lg{align-self:stretch;justify-content:flex-end;margin:6px -16px -16px;padding:13px 16px;background:var(--dm-strip);border-top:1px solid var(--dm-line);border-radius:0 0 var(--dm-r-card) var(--dm-r-card)}
:root[data-style="clean"] .hmx-grid i,:root [data-style="clean"] .hmx-grid i,:root [data-style="clean"].hmx-grid i{transition:background .5s var(--dm-ease),box-shadow var(--dm-t-fast) var(--dm-ease)}
@media (hover:hover) and (pointer:fine){:root[data-style="clean"] .hmx-grid i:hover,:root [data-style="clean"] .hmx-grid i:hover,:root [data-style="clean"].hmx-grid i:hover{transform:none;box-shadow:0 0 0 1px var(--dm-surface),0 0 0 2.5px var(--dm-line-strong)}}

DM.def('activity-heatmap', (r, c) => {
  const DAYS = ['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'];
  const grid = $('.hmx-grid', r), st = $('.hmx-st', r);
  const gen = (who) => { const a = []; for (let d = 0; d < 7; d++) for (let h = 0; h < 24; h++){
    let v = who === 'agent' ? (h >= 1 && h <= 5 ? .75 : h >= 9 && h <= 18 ? .45 : .15) : (h >= 9 && h <= 18 ? .65 : h >= 19 && h <= 22 ? .2 : .03);
    if (d >= 5) v *= who === 'agent' ? .8 : .2; if (who === 'agent' && d === 0 && h === 9) v = 1;
    v = Math.max(0, Math.min(1, v + (Math.sin(d * 7.1 + h * 3.3) * .18))); a.push(v); } return a; };
  const D = { agent:gen('agent'), team:gen('team') };
  grid.innerHTML = Array.from({ length:168 }, () => '<i style="--dm-a:0"></i>').join('');
  const cells = $$('i', grid);
  function draw(w){ cells.forEach((el, i) => { const d = Math.floor(i / 24), h = i % 24, v = D[w][i]; c.later((h + d) * 14, () => el.style.setProperty('--dm-a', (v * .9).toFixed(2)));
    const hr = (h % 12 || 12) + (h < 12 ? 'am' : 'pm'); el.dataset.tip = `${DAYS[d]} ${hr}: ${Math.round(v * (w === 'agent' ? 40 : 25))} ${w === 'agent' ? 'runs' : 'edits'}`; });
    swap(st, w === 'agent' ? 'Busiest overnight, when the queue runs' : 'Busiest 10am to 4pm on weekdays'); }
  seg($('.hmx-sg', r), draw);
  c.later(240, () => draw('agent'));
  // on a phone the grid scrolls sideways: it starts at the latest hours, and fades out on whichever side has more to see
  const sc = $('.hmx-sc', r);
  const edges = () => { const m = sc.scrollWidth - sc.clientWidth; sc.classList.toggle('ml', m > 1 && sc.scrollLeft > 1); sc.classList.toggle('mr', m > 1 && sc.scrollLeft < m - 1); };
  // it stays on the latest hours as the card settles its size, until the person scrolls it themselves
  let moved = false;
  const fit = () => { if (!moved) sc.scrollLeft = sc.scrollWidth; edges(); };
  c.on(sc, 'scroll', edges, { passive:true });
  ['pointerdown', 'wheel', 'touchstart', 'keydown'].forEach(e => c.on(sc, e, () => { moved = true; }, { passive:true }));
  const ro = new ResizeObserver(fit); ro.observe(sc); ro.observe(grid); c.offs.push(() => ro.disconnect());
});
